export const NOX_CHAPTERS=[
 ['처음 켜진 자리','돌아왔구나. 이 등불은 얼굴보다 발소리를 먼저 기억해.'],
 ['문고리의 이름','처음 이 금고엔 보물보다 이름을 보관했어. 잊히지 않으려는 사람들이 왔지.'],
 ['첫 번째 균열','잊고 싶은 이름도 돈을 내기 시작했어. 금고는 그 차이를 몰랐고.'],
 ['등불지기의 손','깜부기의 옛 주인은 문이 무너지는 날까지 돌아오는 사람 수를 셌어.'],
 ['은실의 약속','나는 팔린 기억을 먹지 않아. 다시 불릴 날까지 뿔의 등불에 매달아 두지.'],
 ['기록관의 열쇠','네가 데려온 목소리들이 새 문장을 만들었어. 기록관의 길이 열렸구나.'],
 ['수호자의 심장','맨 아래의 용은 탐욕을 지키는 게 아니야. 모두가 잊은 사람을 지키고 있어.'],
 ['무너진 다리','그 사수는 마지막 사람이 건널 때까지 겨눴대. 마지막 사람은 끝내 오지 않았고.'],
 ['남겨진 대답','돌아오지 않은 이들의 이름을 누가 불러야 할까. 그게 이 금고의 오래된 물음이야.'],
 ['꺼지지 않은 잔','다음 손님 몫은 늘 남겨 둬. 언젠가 올 줄 알았던 손님이 있으니까.'],
 ['합창사의 목소리','열 번째 발소리네. 이제 한 사람의 등불에서 여러 목소리가 들려.'],
 ['금고 바깥의 밤','어느 결말이든 네가 가져온 이름들은 밖에서 이어질 거야. 나도 곧 그 이야기를 듣겠지.'],
];
const STAGE_STORIES=[
 [['깜부기','이번 돌길은 전에 왔던 길과 달라. 금고가 잠든 동안 방들을 옮겼나 봐.'],['도적','그래도 돌아올 문은 기억해 두겠어.']],
 [['깜부기','여기 묻힌 발자국은 다 서두르다가 남은 거래. 수정이 울면 잠깐 멈춰 줘.'],['도적','서두를지 돌아갈지, 지금 가진 기억부터 보지.']],
 [['깜부기','저 쇠판 아래에 누군가 자기 이름을 긁어 놨어. 소리 대신 글자라도 남기려고.'],['도적','읽고 갈게. 발걸음은 가볍게.']],
 [['깜부기','맨 아래에서 내 이름을 부르는 것 같아. 두려운 건 우리만이 아닌가 봐.'],['도적','유물과 함께 그 목소리도 데리고 돌아가자.']],
];
export function stageStory(index,hero='도적'){return (STAGE_STORIES[index]||[]).map(([who,line])=>[who==='도적'?hero:who,line]);}
export function noxChapter(profile){return NOX_CHAPTERS[Math.min(profile.runs,NOX_CHAPTERS.length-1)];}
export function endingStory(choice){return choice==='remember'?[['녹스','이름까지 가져왔구나. 이제 저들은 금고 밖에서도 다시 불릴 거야.'],['깜부기','내 등불이 조금 덜 무거워졌어. 이 불빛은 놓아준 기억들이 남긴 자리인가 봐.']]:[['녹스','문을 닫아 주었구나. 잠들고 싶었던 기억들은 이제 고요할 거야.'],['깜부기','모든 발자국을 따라갈 필요는 없었네. 돌아온 네 발소리는 내가 기억할게.']];}
